 public static void Run(){int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;}Check(NativePosition.GetWindowStyle(IntPtr.Zero,-20)==IntPtr.Zero,"native window-style interop matches process architecture");Check(Video.Parse("https://youtu.be/M7lc1UVf-VE?t=1m30s").Start==90,"timestamp");Check(Video.Parse("https://www.youtube.com/shorts/M7lc1UVf-VE").Id=="M7lc1UVf-VE","shorts");Check(Video.Parse("https://www.youtube.com/live/M7lc1UVf-VE").Id=="M7lc1UVf-VE","live");Check(Video.Parse("https://www.youtube.com/watch?v=M7lc1UVf-VE&list=PL1234567890").Playlist=="PL1234567890","playlist");Check(Video.Parse("https://www.youtube.com/playlist?list=PL1234567890").Id=="","playlist-only");foreach(var bad in new[]{"https://youtube.com.evil.com/watch?v=M7lc1UVf-VE","javascript:alert(1)","file:///C:/Windows/test","https://www.youtube.com/watch?v=<script>","https://evil.com/","https://www.youtube.com:8443/watch?v=M7lc1UVf-VE"}){bool rejected=false;try{Video.Parse(bad);}catch(FormatException){rejected=true;}Check(rejected,"reject "+bad);}var p=new Preferences{Last=new Video("M7lc1UVf-VE","",12)};p.Queue.Add(new Video("M7lc1UVf-VE"));var restored=JsonSerializer.Deserialize<Preferences>(JsonSerializer.Serialize(p))!;Check(restored.Last!.Start==12&&restored.Queue.Count==1,"roundtrip");File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"tests.json"),JsonSerializer.Serialize(new{passed,at=DateTimeOffset.Now}));}
